#!/usr/bin/env python3
from __future__ import annotations
import csv, json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
S=ROOT/'data/data_resources.csv'; P=ROOT/'data/data_products.csv'; D=ROOT/'data/product_distributions.csv'; B=ROOT/'data/brazil_scope_priorities.json'
DATE='2026-08-18'

def read(path):
    with path.open(encoding='utf-8-sig',newline='') as f: return list(csv.DictReader(f))

def append_rows(path, rows):
    with path.open(encoding='utf-8-sig',newline='') as f:
        fields=csv.DictReader(f).fieldnames
    with path.open('a',encoding='utf-8',newline='') as f:
        w=csv.DictWriter(f,fieldnames=fields,lineterminator='\n',extrasaction='raise')
        for r in rows: w.writerow(r)

sources=read(S); products=read(P); dists=read(D)
assert len(sources)==125 and len(products)==756 and len(dists)==787, (len(sources),len(products),len(dists))
assert sources[-1]['resource_id']=='DR0125' and products[-1]['product_id']=='DP000760' and dists[-1]['distribution_id']=='DD000791'
